package com.xianyusmart.service;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
public class PdcaProgressSnapshotTest {
    static final ObjectMapper JSON=new ObjectMapper();
    public static ObjectNode sample() {
        String now=Instant.now().minusSeconds(10).toString();
        var n=JSON.createObjectNode();n.put("schemaVersion",1).put("tenantId",1).put("revision","9223372036854775808").put("sourceRevision","source-1").put("sourceLedgerSha256","a".repeat(64)).put("coverageDefinition","登记项数量，含版本来源；不是独立功能分母").put("coverageComplete",false).put("publishedByRole","D2");
        for(String k:new String[]{"generatedAt","updatedAt","sourceObservedAt","lastSuccessfulPublishAt"})n.put(k,now);
        n.putArray("sourceTitles").addObject().put("sourceId","src-abc").put("safeTitle","隔离合成来源");
        var inv=n.putObject("inventory");inv.put("ledgerSourceRecordCount",1).put("additionalRequirementOrGateCount",0).put("defectRecordCount",0).putNull("independentFeatureDenominator").putNull("acceptedCurrentCandidateCount");
        var roles=n.putArray("roles");for(String role:new String[]{"P","D2","C","A"}){var r=roles.addObject();r.put("role",role).put("sourceRef","src-abc").put("responsibility","合成隔离职责").put("currentBatch","R03").put("state","WAITING").put("updatedAt",now).put("nextStep","等待当前候选证据");r.putArray("blockers");}
        n.putArray("evidenceCatalog").addObject().put("evidenceId","dev-evidence").put("safeTitle","开发隔离证据").put("kind","D_DEV").putNull("candidateVersion").putNull("candidateSha").put("safeSummary","不代C签字").put("sourceRef","src-abc").put("observedAt",now);
        var item=n.putArray("items").addObject();item.put("key","item-"+"a".repeat(24)).put("originalId","R03-01").put("requirementId","R03-01").put("sourceRef","src-abc").put("recordKind","ACCEPTANCE_CHECK").put("title","合成检查").put("batch","R03").put("ownerRole","C").put("implementationState","UNKNOWN").put("devState","IN_DEVELOPMENT").put("checkState","NOT_CHECKED").put("releaseState","NOT_RELEASED").put("severity","UNKNOWN").put("blockerType","EVIDENCE").put("blockerSummary","尚未验收").put("nextStep","执行安全验收").put("updatedAt",now);item.putArray("evidenceIds").add("dev-evidence");n.putArray("bugs");return n;
    }
    static byte[] bytes(ObjectNode n)throws Exception{return JSON.writeValueAsBytes(n);}
    @Test void validUnknownSnapshotRetainsLongRevisionAndSeparateRecordKinds()throws Exception{var s=PdcaProgressSnapshot.parse(bytes(sample()),1);assertEquals("9223372036854775808",s.metadata().get("revision"));assertEquals("ACCEPTANCE_CHECK",s.items().getFirst().get("recordKind"));assertTrue(s.bugs().isEmpty());}
    @Test void plainComparisonAndProductDescriptionAreSafeText()throws Exception{for(String title:new String[]{"列表 P95<2s，筛选反馈<300ms", "裸机应用+Docker MySQL", "before=0/now>0 不计算无穷百分比"}){var n=sample();((ObjectNode)n.get("items").get(0)).put("title",title);assertEquals(title,PdcaProgressSnapshot.parse(bytes(n),1).items().getFirst().get("title"));}}
    @Test void typedOpaqueHashesAreNotFreeTextContactNumbers()throws Exception{var n=sample();String source="src-13812345678abcde";((ObjectNode)n.get("sourceTitles").get(0)).put("sourceId",source);for(var collection:List.of("roles","items","evidenceCatalog"))for(var row:n.get(collection))((ObjectNode)row).put("sourceRef",source);((ObjectNode)n.get("items").get(0)).put("key","item-13812345678"+"a".repeat(13));n.put("sourceLedgerSha256","13812345678"+"a".repeat(53));assertEquals(1,PdcaProgressSnapshot.parse(bytes(n),1).items().size());}
    @Test void privateUnknownNestedOrUnsafeTextRejectsEntireProjection()throws Exception{for(String value:new String[]{"Cookie=SYNTHETIC_PRIVATE","<script>bad</script>","/Users/test/private", "curl https://example.invalid"}){var n=sample();((ObjectNode)n.get("items").get(0)).put("title",value);assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));}var n=sample();n.putObject("private").put("secret","synthetic");assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));}
    @Test void tenantUnsupportedSchemaAndMissingReferencesReject()throws Exception{var n=sample();n.put("tenantId",2);assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));n.put("tenantId",1).put("schemaVersion",2);assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));n.put("schemaVersion",1);((ObjectNode)n.get("items").get(0)).putArray("evidenceIds").add("missing");assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));}
    @Test void devEvidenceCannotBecomeCurrentAcceptanceOrCompleteCoverage()throws Exception{var n=sample();var item=(ObjectNode)n.get("items").get(0);item.put("implementationState","ACCEPTED").put("checkState","PASSED_ISOLATED");assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));item.put("implementationState","UNKNOWN");n.put("coverageComplete",true);assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));}
    @Test void historicalDevOrCandidateLessCReferencesCannotCloseCurrentItemOrBug()throws Exception{
        for(String kind:new String[]{"HISTORICAL","D_DEV","C_ACCEPTANCE"}){var n=sample();var item=(ObjectNode)n.get("items").get(0);item.put("implementationState","ACCEPTED").put("checkState","PASSED_ISOLATED");((ObjectNode)n.get("evidenceCatalog").get(0)).put("kind",kind);assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));}
    }
    @Test void duplicateKeysInventoriesAndJsonFieldsReject()throws Exception{var n=sample();n.withArray("items").add(n.get("items").get(0).deepCopy());assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(n),1));var clean=sample();clean.withObject("inventory").put("defectRecordCount",1);assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(bytes(clean),1));String json=JSON.writeValueAsString(sample()).replace("\"schemaVersion\":1","\"schemaVersion\":2,\"schemaVersion\":1");assertThrows(IllegalArgumentException.class,()->PdcaProgressSnapshot.parse(json.getBytes(java.nio.charset.StandardCharsets.UTF_8),1));}
}
